DO $$DECLARE t uuid;BEGIN FOR t IN SELECT id FROM sys_tenant LOOP PERFORM set_config('crm.tenant_id',t::text,true);UPDATE sys_role_policy SET campaign_can_read=contact_can_read OR lead_can_read,campaign_can_write=contact_can_write OR lead_can_write,campaign_can_launch=role_code='SALES_MANAGER' AND(contact_can_write OR lead_can_write),version=version+1 WHERE tenant_id=t;END LOOP;PERFORM set_config('crm.tenant_id','',true);END$$;
CREATE TABLE crm_campaign(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,name varchar(200) NOT NULL,description varchar(4000) NOT NULL DEFAULT '',owner_member_id uuid NOT NULL,
 channel varchar(20) NOT NULL CHECK(channel IN('FOLLOW_UP','EMAIL_DRAFT')),status varchar(20) NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','SCHEDULED','RUNNING','COMPLETED','CANCELLED','BLOCKED')),
 budget_cents bigint NOT NULL CHECK(budget_cents BETWEEN 0 AND 100000000000),subject varchar(200) NOT NULL,body varchar(4000) NOT NULL,task_due_date date NOT NULL,
 scheduled_at timestamptz,launch_by_member_id uuid,launch_auth_version bigint,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,owner_member_id) REFERENCES sys_tenant_member(tenant_id,id),FOREIGN KEY(tenant_id,launch_by_member_id) REFERENCES sys_tenant_member(tenant_id,id));
CREATE TABLE crm_campaign_member(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,campaign_id uuid NOT NULL,contact_id uuid,lead_id uuid,status varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','REMOVED')),
 version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),CHECK((contact_id IS NOT NULL)<>(lead_id IS NOT NULL)),FOREIGN KEY(tenant_id,campaign_id) REFERENCES crm_campaign(tenant_id,id),FOREIGN KEY(tenant_id,contact_id) REFERENCES crm_contact(tenant_id,id),FOREIGN KEY(tenant_id,lead_id) REFERENCES crm_lead(tenant_id,id));
CREATE UNIQUE INDEX campaign_contact_unique ON crm_campaign_member(tenant_id,campaign_id,contact_id) WHERE contact_id IS NOT NULL AND status='ACTIVE';
CREATE UNIQUE INDEX campaign_lead_unique ON crm_campaign_member(tenant_id,campaign_id,lead_id) WHERE lead_id IS NOT NULL AND status='ACTIVE';
CREATE TABLE crm_campaign_revision(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,campaign_id uuid NOT NULL,business_version bigint NOT NULL,action varchar(40) NOT NULL,snapshot jsonb NOT NULL,reason varchar(1000) NOT NULL DEFAULT '',actor_member_id uuid NOT NULL,actor_name_snapshot varchar(100) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,campaign_id,business_version),FOREIGN KEY(tenant_id,campaign_id) REFERENCES crm_campaign(tenant_id,id),FOREIGN KEY(tenant_id,actor_member_id) REFERENCES sys_tenant_member(tenant_id,id));
CREATE TABLE crm_campaign_execution(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,campaign_id uuid NOT NULL,member_id uuid NOT NULL,execution_version bigint NOT NULL,kind varchar(20) NOT NULL CHECK(kind IN('FOLLOW_UP','EMAIL_DRAFT')),task_id uuid,draft_subject varchar(200),draft_body varchar(5000),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,campaign_id,member_id),FOREIGN KEY(tenant_id,campaign_id) REFERENCES crm_campaign(tenant_id,id),FOREIGN KEY(tenant_id,member_id) REFERENCES crm_campaign_member(tenant_id,id),FOREIGN KEY(tenant_id,task_id) REFERENCES crm_task(tenant_id,id));
CREATE TABLE crm_campaign_result(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,campaign_id uuid NOT NULL,member_id uuid NOT NULL,outcome varchar(20) NOT NULL CHECK(outcome IN('CONTACTED','RESPONDED','CONVERTED','NO_RESPONSE','OPT_OUT')),cost_cents bigint NOT NULL CHECK(cost_cents BETWEEN 0 AND 100000000000),notes varchar(2000) NOT NULL DEFAULT '',actor_member_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,campaign_id) REFERENCES crm_campaign(tenant_id,id),FOREIGN KEY(tenant_id,member_id) REFERENCES crm_campaign_member(tenant_id,id),FOREIGN KEY(tenant_id,actor_member_id) REFERENCES sys_tenant_member(tenant_id,id));
CREATE TABLE crm_marketing_consent(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,contact_id uuid,lead_id uuid,channel varchar(20) NOT NULL CHECK(channel IN('FOLLOW_UP','EMAIL_DRAFT')),state varchar(20) NOT NULL CHECK(state IN('OPT_IN','OPT_OUT')),source varchar(200) NOT NULL,evidence varchar(1000) NOT NULL,actor_member_id uuid NOT NULL,version bigint NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),CHECK((contact_id IS NOT NULL)<>(lead_id IS NOT NULL)),FOREIGN KEY(tenant_id,contact_id) REFERENCES crm_contact(tenant_id,id),FOREIGN KEY(tenant_id,lead_id) REFERENCES crm_lead(tenant_id,id),FOREIGN KEY(tenant_id,actor_member_id) REFERENCES sys_tenant_member(tenant_id,id));
CREATE UNIQUE INDEX consent_contact_unique ON crm_marketing_consent(tenant_id,contact_id,channel) WHERE contact_id IS NOT NULL;
CREATE UNIQUE INDEX consent_lead_unique ON crm_marketing_consent(tenant_id,lead_id,channel) WHERE lead_id IS NOT NULL;
DO $$DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['crm_campaign','crm_campaign_member','crm_campaign_revision','crm_campaign_execution','crm_campaign_result','crm_marketing_consent'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',n);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',n);EXECUTE format('CREATE POLICY tenant_boundary ON %I USING(tenant_id=nullif(current_setting(''crm.tenant_id'',true),'''')::uuid) WITH CHECK(tenant_id=nullif(current_setting(''crm.tenant_id'',true),'''')::uuid)',n);END LOOP;END$$;
GRANT SELECT,INSERT,UPDATE ON crm_campaign,crm_campaign_member,crm_marketing_consent TO crm_runtime;
GRANT SELECT,INSERT ON crm_campaign_revision,crm_campaign_execution,crm_campaign_result TO crm_runtime;
